function healthDbRow(summary,userId){return {user_id:userId,observed_on:summary.observedOn||null,imported_at:summary.importedAt||new Date().toISOString(),source_file_name:summary.sourceFileName||null,source_format:summary.sourceFormat||null,steps:summary.steps??null,step_goal:summary.stepGoal??null,sleep_minutes:summary.sleepMinutes??null,active_calories:summary.activeCalories??null,total_calories:summary.totalCalories??null,resting_heart_rate:summary.restingHeartRate??null,average_heart_rate:summary.averageHeartRate??null,stress_average:summary.stressAverage??null,hrv_ms:summary.hrvMs??null,latest_activity:summary.latestActivity||null,raw_summary:summary};}
      function healthFromDb(row){return row?{...(row.raw_summary||{}),observedOn:row.observed_on,importedAt:row.imported_at,sourceFileName:row.source_file_name,sourceFormat:row.source_format,steps:row.steps,stepGoal:row.step_goal,sleepMinutes:row.sleep_minutes,activeCalories:row.active_calories,totalCalories:row.total_calories,restingHeartRate:row.resting_heart_rate,averageHeartRate:row.average_heart_rate,stressAverage:row.stress_average,hrvMs:row.hrv_ms,latestActivity:row.latest_activity}:null;}
      async function syncHealthWithSession(session){const privacy=document.getElementById('healthPrivacy');if(!session?.user){privacy.textContent='Données locales tant que vous n’êtes pas connecté.';return;}try{const client=supabaseClient||await loadSupabase();if(healthSummary){const result=await client.from('health_snapshots').upsert(healthDbRow(healthSummary,session.user.id),{onConflict:'user_id'});if(result.error)throw result.error;privacy.textContent='Synchronisé dans votre espace Supabase privé.';}else{const result=await client.from('health_snapshots').select('*').eq('user_id',session.user.id).maybeSingle();if(result.error)throw result.error;if(result.data){const remote=healthFromDb(result.data);paintHealth(remote);saveHealthLocal(remote);healthStatus.textContent=`Données retrouvées${remote.observedOn?` · ${remote.observedOn}`:''}.`;privacy.textContent='Synchronisé dans votre espace Supabase privé.';}else privacy.textContent='Connecté · aucune donnée santé enregistrée.';}}catch(error){privacy.textContent='Données conservées localement · synchronisation indisponible.';}}
